"""Binary search over a sorted sequence."""


def bsearch(sorted_items, target):
    lo, hi = 0, len(sorted_items)
    while lo < hi:
        mid = (lo + hi) // 2
        if sorted_items[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
    return lo

files.topk.py:
"""Largest-k selection."""


def topk(items, k):
    if k < 0:
        raise ValueError("k must be non-negative")
    return sorted(items)[:k]

